"Недоступно, поки експедиція в дорозі": "Unavailable while an expedition is away",
"Ключів поки немає.": "No keys yet.",
"Фільтр увімкнено": "Filter on",
"Працює": "Active",
"Оберіть рідкість": "Choose a rarity",
"Вимкнено": "Off",
"Позначені рідкості зброї та броні, що випадуть у бою, одразу викидаються": "Weapons and armour of the marked rarities that drop in battle are thrown away at once",
"і не займають місця в інвентарі. Речі, які вже лежать в інвентарі, ключі, зілля й матеріали фільтр не чіпає.": "and take no inventory space. Items already in the inventory, keys, potions and materials are not affected by the filter.",
"Фільтр здобичі: увімкнено (": "Loot filter: on (",
"Фільтр здобичі: вимкнено": "Loot filter: off",
"Незнайомець": "Stranger",
"До вас підходить хтось у запиленому плащі з глибоким каптуром — обличчя не видно. Він ніби випадково зачіпає вас плечем": "Someone in a dusty cloak with a deep hood comes up to you — the face is hidden. He seems to brush your shoulder by accident",
"і щось тихо кладе вам у торбу. «Тобі воно потрібніше», — чуєте ви шепіт, а коли обертаєтеся, незнайомця вже й слід простиг.": "and quietly slips something into your bag. \"You need it more,\" you hear a whisper, and when you turn around, the stranger is long gone.",
"У торбі — важка куля з темного каменю, тепла на дотик. На одному боці — глибоке заглиблення у формі ромба.": "In the bag is a heavy ball of dark stone, warm to the touch. On one side there is a deep diamond-shaped hollow.",
"Отримано: Дивна сфера (квестовий предмет). Розпитайте людей, що це може бути.": "Received: Strange Orb (quest item). Ask people what it might be.",
"Ви обережно згортаєте клапоть і ховаєте в торбу.": "You carefully fold the scrap and hide it in your bag.",
"Ніхто не пише в ній чорнилом: щойно герой здолає великого ворога, сторінки наповнюються самі.": "No one writes in it with ink: as soon as the hero defeats a great enemy, the pages fill by themselves.",
"Так нащадки знатимуть, хто проливав кров, щоб зупинити кров Іггдрасиля.": "So that descendants will know who shed blood to stop the blood of Yggdrasil.",
"Перших сторінок Прологу бракує — їх вирвано, лишилися тільки обгорілі корінці.": "The first pages of the Prologue are missing — they were torn out, only burnt stubs remain.",
"Ця сторінка ще чиста. Її напише перемога, якої поки не було…": "This page is still blank. It will be written by a victory that has not yet happened…",
