"Повернутися в меню": "Back to the menu",
"Розпочатих квестів немає. Завдання дає Артеміда, адміністратор гільдії — Дубова Застава, Південний район.": "No quests started. Tasks are given by Artemida, the guild administrator — Oak Outpost, Southern District.",
