"Зменшує фізичну шкоду, яку отримує герой.": "Reduces the physical damage the hero takes.",
"Зменшує магічну шкоду, яку отримує герой.": "Reduces the magical damage the hero takes.",
"Як часто герой ходить у бою.": "How often the hero acts in battle.",
"Шанс завдати посиленого (критичного) удару.": "Chance to deal an empowered (critical) hit.",
"Шанс повністю ухилитися від фізичного удару.": "Chance to fully dodge a physical strike.",
"Шанс заблокувати половину фізичної шкоди.": "Chance to block half of the physical damage.",
"Шанс заблокувати половину магічної шкоди.": "Chance to block half of the magical damage.",
"Скільки здоров'я відновлюється з часом поза боєм (у Домівці — швидше).": "How much health regenerates over time outside battle (faster at Home).",
"Скільки мани відновлюється з часом поза боєм (у Домівці — швидше).": "How much mana regenerates over time outside battle (faster at Home).",
"Бонус володіння зброєю до швидкості.": "Weapon mastery bonus to speed.",
"Посилює всі навички однаково: фізичні удари (від Атаки), заклинання (від Сили магії) і лікування. Дають речі (випадковий бонус) і руна Манназ.": "Strengthens all skills equally: physical strikes (from Attack), spells (from Magic Power) and healing. Granted by items (random bonus) and the Mannaz rune.",
