"В інвентарі немає мішечків. Їх можна вибити з босів — шанс 1% з кожного переможеного боса.": "There are no pouches in the inventory. They drop from bosses — a 1% chance from each defeated boss.",
"Натисніть порожній слот, щоб повісити мішечок з інвентаря, або зайнятий — щоб зняти його.": "Press an empty slot to hang a pouch from the inventory, or an occupied one to remove it.",
"Усе": "All",
"Перекласти": "Move",
"Руни зброї лягають у зброю та речі лівої руки, руни броні — у броню, універсальні — у будь-що. Вийнята з гнізда руна тріскається і стає зламаною.": "Weapon runes go into weapons and left-hand items, armour runes into armour, universal ones into anything. A rune taken out of a socket cracks and becomes broken.",
