"Експедиція · руда": "Expedition · ore",
"Експедиція · деревина": "Expedition · wood",
"Без дороги — лише експедиція (3 або 6 героїв, 4 год)": "No road — expedition only (3 or 6 heroes, 4 h)",
"Сюди прямуєте": "Heading here",
"Ви в дорозі": "You are travelling",
"Туди немає дороги.": "There is no road there.",
"Видобуток за кожен виграний бій:": "Yield for each battle won:",
"Вороги — з усього світу (без босів):": "Enemies — from all over the world (no bosses):",
"Вороги:": "Enemies:",
"Відправити експедицію · 4 год": "Send an expedition · 4 h",
"Спершу заберіть здобич повернених експедицій.": "First collect the loot of the returned expeditions.",
"До Шахти й Лісопилки немає дороги: туди лише відправляють експедицію з мапи.": "There is no road to the Mine and the Sawmill: only expeditions are sent there from the map.",
"Поки експедиція в дорозі, переходити між локаціями не можна — доступні лише «Персонаж», «Інвентар», «Мапа», «Налаштування» і «Головне меню».": "While an expedition is away you cannot move between locations — only \"Character\", \"Inventory\", \"Map\", \"Settings\" and \"Main Menu\" are available.",
"Ви тут — відкрити локацію": "You are here — open the location",
"Переміщення не можна скасувати; у дорозі доступні лише «Персонаж», «Інвентар» і «Мапа».": "The move cannot be cancelled; while travelling only \"Character\", \"Inventory\" and \"Map\" are available.",
"полеглий": "fallen",
"в експедиції": "on an expedition",
"Група 4 години безперервно б'ється з ворогами локації (без босів). На бої з чемпіонами погоджується сама.": "For 4 hours the party fights the location's enemies non-stop (no bosses). It accepts fights with champions on its own.",
"Здобич — як у звичайних боях": "Loot — as in ordinary battles",
"Експедиція повертається, коли мине час або коли загинуть усі її герої. Між боями група стає на привал.": "The expedition returns when the time runs out or when all its heroes die. Between battles the party makes camp.",
"Автозілля вимкнено (Налаштування) — в експедиції зілля не п'ють, лише привал.": "Auto-potions are off (Settings) — on an expedition no potions are drunk, only camp rest.",
"Поки експедиція в дорозі, переходити між локаціями не можна — доступні лише «Персонаж», «Інвентар», «Мапа», «Налаштування» і «Головне меню». Її герої не міняють речей і їх не можна звільнити.": "While an expedition is away you cannot move between locations — only \"Character\", \"Inventory\", \"Map\", \"Settings\" and \"Main Menu\" are available. Its heroes don't change items and cannot be dismissed.",
"З тих, хто лишився вдома, можна відправити ще одну експедицію (одночасно — дві по 3 героя або одна на 6). Будьте обережні: чемпіони (утричі сильніші) трапляються часто, а полеглі до кінця експедиції не встають.": "From those who stayed at home you can send another expedition (at the same time — two of 3 heroes or one of 6). Be careful: champions (three times stronger) appear often, and the fallen don't get up until the expedition ends.",
"Закрито — світ відкриється згодом.": "Closed — the world will open later.",
"Дев'ять світів Іггдрасиля": "The Nine Worlds of Yggdrasil",
